<?php
if(PHP_SAPI!=='cli'||getenv('PHPBB_ARCADE_SUMMARY_NATIVE')!=='1'){echo "Arcade summary checks require an explicitly enabled disposable database.\n";return;}
require __DIR__.'/arcade-summary-fixture.php';require $as_app.'db/mysqli.php';
class ArcadeSummaryNativeDatabase extends sql_db
{
	var $setup=true;var $queries=array();var $opened=0;var $fail_score=false;
	function sql_query($sql='',$transaction=false){if(!$this->setup&&!preg_match('/^SELECT\b/i',ltrim($sql))){throw new RuntimeException('Summary rendering must remain read-only');}$this->queries[]=$sql;if($this->fail_score&&strpos($sql,'SELECT s.score, u.username')===0){return false;}$r=parent::sql_query($sql,$transaction);if($r&&!$this->setup){$this->opened++;}return$r;}
	function sql_freeresult($result=false){if(!$this->setup){$this->opened--;}return parent::sql_freeresult($result);}
}
function an_sql($sql){$r=$GLOBALS['db']->sql_query($sql);as_check($r!==false,'Own canonical Arcade fixture SQL');return$r;}
function an_change($sql){$GLOBALS['db']->setup=true;try{return an_sql($sql);}finally{$GLOBALS['db']->setup=false;}}
function an_snapshot(){global $db;$data=array();foreach(array('users','ina_user_data','ina_games','ina_scores')as$table){$r=an_sql('SELECT * FROM fixture_'.$table);$rows=$db->sql_fetchrowset($r);$db->sql_freeresult($r);$rows=array_map('json_encode',$rows);sort($rows);$data[$table]=$rows;}return$data;}
$db=$control=null;$created=false;$schema='codex_arc_summary_'.bin2hex(phpbb_random_bytes(8));
try{as_open();$port=getenv('PHPBB_ARCADE_SUMMARY_PORT')?:'3306';$password=getenv('PHPBB_ARCADE_SUMMARY_PASSWORD')?:'';as_check(preg_match('/^[0-9]{1,5}$/D',$port)&&(int)$port>0&&(int)$port<=65535,'Owned loopback port');$host='127.0.0.1:'.$port;$control=new sql_db($host,'root',$password,'',false);as_check((bool)$control->db_connect_id,'Own local server connection');as_check(preg_match('/^codex_arc_summary_[a-f0-9]{16}$/D',$schema)&&$control->sql_query('CREATE DATABASE '.$schema.' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci'),'Exclusive native schema');$created=true;
	$db=new ArcadeSummaryNativeDatabase($host,'root',$password,$schema,false);as_check((bool)$db->db_connect_id,'Own schema connection');$canonical=file_get_contents($as_app.'install/schemas/mysql_schema.sql');foreach(array('users','ina_user_data','ina_games','ina_scores')as$name){as_check(preg_match('/CREATE TABLE phpbb_'.preg_quote($name,'/').' \(.*?\) ENGINE=InnoDB[^;]*;/s',$canonical,$m)===1,'Exact canonical schema');an_sql(str_replace('phpbb_'.$name,'fixture_'.$name,$m[0]));}
	foreach(array('english','german')as$locale){as_language($locale);foreach(array('A&B',"O'Reilly",'&#39;','Grüße 😀')as$raw){foreach(array(ENT_QUOTES,ENT_COMPAT)as$flags){
		$db->setup=true;foreach(array('users','ina_user_data','ina_games','ina_scores')as$table){an_sql('DELETE FROM fixture_'.$table);}$key=$db->sql_escape(phpbb_username_key($raw,$flags));an_sql("INSERT INTO fixture_users(user_id,username,user_password) VALUES(7,'$key',''),(8,'Runner up','')");an_sql('INSERT INTO fixture_ina_user_data(user_id,first_places,at_first_places,last_won_date) VALUES(7,4,1,1),(8,2,9,2)');an_sql("INSERT INTO fixture_ina_games(game_name,game_desc) VALUES('fixture_game','Literal &amp; <caption>')");an_sql("INSERT INTO fixture_ina_scores(game_name,player_id,score,date) VALUES('fixture_game',7,1234.5000,100)");$db->setup=false;as_clear();$before=an_snapshot();
		$SID='sid=native_first';$out=best_player();as_check(strpos($out,htmlspecialchars($raw,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'))!==false,'Native canonical account renders once');as_links($out,7,'native_first',4);$as_cases++;
		$n=count($db->queries);$SID='sid=native_second';$out=best_player();as_check(count($db->queries)===$n+1&&strpos(end($db->queries),'SELECT user_id, username')===0,'Native cache hit only refreshes current account');as_links($out,7,'native_second',4);$as_cases++;
		$out=best_player('at_first_places');as_check(strpos($out,'Runner up')!==false,'Actual all-time leaderboard uses independent counter');as_links($out,8,'native_second',1);$as_cases++;
		$out=last_played_score();as_check(strpos($out,htmlspecialchars($raw,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'))!==false&&strpos($out,'1,234.5')!==false&&strpos($out,'Literal &amp;amp; &lt;caption&gt;')!==false,'Native joined latest score preserves account, numeric score and raw caption contracts');$as_cases++;
		as_check(an_snapshot()===$before&&$db->opened===0,'All renderers preserve canonical rows and release every result');
	}}}
	$new=phpbb_username_key('Renamed & Member');an_change("UPDATE fixture_users SET username='".$db->sql_escape($new)."' WHERE user_id=7");$out=best_player();as_check(strpos($out,'Renamed &amp; Member')!==false,'Cache cannot retain old name after native rename');$as_cases++;
	an_change('DELETE FROM fixture_users WHERE user_id=7');$out=best_player();as_check(strpos($out,'Renamed')===false&&strpos($out,'Runner up')!==false,'Missing cached identity triggers fresh JOIN and next surviving winner');as_links($out,8,'native_second',4);as_check(as_payload('best_player')['data']['user_id']===8,'Deleted winner identity is replaced in data cache');$as_cases++;
	as_clear();an_change('UPDATE fixture_ina_user_data SET first_places=0');$out=best_player();as_check($out!==''&&as_payload('best_player')['data']['wins']===0,'A zero counter is a real cached leaderboard result');$as_cases++;
	as_clear();an_change('UPDATE fixture_ina_user_data SET first_places=8388607 WHERE user_id=8');$out=best_player();as_check(strpos($out,'8388607')!==false&&as_payload('best_player')['data']['wins']===8388607,'Native maximum canonical counter is preserved');$as_cases++;
	$db->fail_score=true;as_check(last_played_score()===''&&$db->opened===0,'Native score read failure is controlled and does not leak query text');$db->fail_score=false;$as_cases++;
	an_change('DELETE FROM fixture_ina_scores');as_check(last_played_score()==='','Actual empty score history returns no fabricated entry');$as_cases++;
	as_clear();an_change('DELETE FROM fixture_ina_user_data');as_check(best_player()==='','Actual empty leaderboard returns no fabricated winner');$as_cases++;
	echo 'Arcade summaries native: ',$as_cases,' cases, ',$as_checks," assertions PASS; canonical MariaDB JOINs, real cache methods, session links, independent counters, rename/deletion, raw captions and read-only rendering.\n";
}finally{if($db){$db->sql_close();}if($created){as_check(preg_match('/^codex_arc_summary_[a-f0-9]{16}$/D',$schema)&&$control->sql_query('DROP DATABASE '.$schema),'Exact own schema cleanup');}if($control){$control->sql_close();}as_close();restore_error_handler();}
